using System;
using System.Collections.Generic;
using System.Linq;

namespace Deviant.Run
{
    // One card's runtime values (docs/design/progression/maintenance-augments.md). Ratios are additive fractions
    // (+0.12 = +12%); zero means the card has no such effect. Generated by tools/combat/export_maintenance_augments.py.
    [Serializable]
    public sealed class AugmentEffect
    {
        public float damage, weaponDamage, basicDamage, skillDamage, incoming, maxHealth, healing, walkSpeed, basicSpeed, skillCooldown, critChance;
        public float executeThreshold, executeDamage, eliteBossWeaponDamage;
        public float sameEnemyHits, sameEnemyExtra, attackHits, attackExtra, signHits, signExtra;
        public float lowHealthThreshold, lowHealthDamage, highHealthDamage;
        public float unhurtMaxDamage, unhurtGainPerSecond, hurtDamage, hurtSeconds;
        public float nearbyRadius, aloneDamage, crowdDamage, frontWeaponDamage, backIncoming;
        public float everyAttack, everyAttackDamage, otherAttackDamage, switchFirstDamage, repeatAttackDamage;
        public float leechRatio, leechMaxHeal, leechCooldown;
        public float growthStartRatio, growthKills, growthStepRatio, growthFinalRatio;
        public float reflectDamageMultiplier, projectileIncoming, bookmarkSeconds;
    }

    [Serializable] public sealed class AugmentGroup { public string id, name; }

    [Serializable]
    public sealed class AugmentDefinition
    {
        public string id, group, name, gain, cost, play, note;
        public AugmentEffect effect;
        public bool Stable => group == MaintenanceAugments.StableGroup;
    }

    [Serializable]
    public sealed class AugmentCatalog
    {
        public int schema, offeredCards, stableCards, riskCards;
        public float minimumDamageScale, minimumIncomingScale, minimumMaxHealthScale, minimumWalkSpeedScale, minimumBasicSpeedScale;
        public float maximumSkillCooldownReduction, maximumCritChance;
        public AugmentGroup[] groups;
        public AugmentDefinition[] augments;

        public AugmentDefinition Find(string id) => augments == null ? null : Array.Find(augments, a => a.id == id);
        public string GroupName(string id) => groups?.FirstOrDefault(g => g.id == id)?.name ?? id;

        public void Validate()
        {
            if (schema != 1 || augments == null || augments.Length == 0 || groups == null) throw new ArgumentException("정비소 증강 데이터 오류");
            if (offeredCards != 3 || stableCards != 1 || riskCards != 2) throw new ArgumentException("정비소 증강 제안은 안정형 1장·도박형 2장입니다.");
            if (!(minimumDamageScale > 0) || !(minimumIncomingScale > 0) || !(minimumMaxHealthScale > 0) || !(minimumWalkSpeedScale > 0) || !(minimumBasicSpeedScale > 0) ||
                !(maximumSkillCooldownReduction > 0 && maximumSkillCooldownReduction < 1) || !(maximumCritChance > 0 && maximumCritChance <= 1))
                throw new ArgumentException("정비소 증강 공통 규칙 오류");
            var ids = new HashSet<string>();
            foreach (var a in augments)
            {
                if (a == null || string.IsNullOrEmpty(a.id) || !ids.Add(a.id) || a.effect == null || string.IsNullOrEmpty(a.name)) throw new ArgumentException("정비소 증강 카드 오류: " + a?.id);
                if (!groups.Any(g => g.id == a.group)) throw new ArgumentException("정비소 증강 계열 오류: " + a.id);
            }
        }
    }

    // Run-scoped augments (docs/design/progression/maintenance-augments.md): free three-card draws for the boss clear and
    // the seal reward chest, the owned cards (each at most once) and the additive totals the combat reads. Lives in
    // WeaponGrowth so chapter 2 keeps it with the rest of the run growth. Augments are never sold (user decision 2026-11-13).
    public sealed class MaintenanceAugments
    {
        public const string StableGroup = "safe";
        readonly List<AugmentDefinition> owned = new List<AugmentDefinition>();
        // 성장통: the maximum-health ratio of the other cards when it was taken (its "max health before selection").
        readonly Dictionary<string, float> growthBasis = new Dictionary<string, float>();
        readonly Random random;

        public AugmentCatalog Catalog { get; }
        public IReadOnlyList<AugmentDefinition> Owned => owned;
        // Enemies defeated by the player since a growth card (성장통) was taken.
        public int GrowthKills { get; private set; }
        public int Revision { get; private set; }

        public MaintenanceAugments(AugmentCatalog catalog, int seed)
        {
            Catalog = catalog ?? throw new ArgumentNullException(nameof(catalog));
            catalog.Validate();
            random = new Random(seed);
        }

        public bool Has(string id) => owned.Any(a => a.id == id);
        public float Sum(Func<AugmentEffect, float> field) { float total = 0; foreach (var a in owned) total += field(a.effect); return total; }
        public IEnumerable<AugmentDefinition> With(Func<AugmentEffect, float> field) => owned.Where(a => field(a.effect) != 0);

        // Cards the profile has not locked away (roguelite-progression.md 잉크와 증강 묶음); set once at departure.
        readonly HashSet<string> lockedCards = new HashSet<string>();
        public void LockCards(IEnumerable<string> ids)
        {
            if (owned.Count > 0) throw new InvalidOperationException("증강 잠금은 출발 시에만 설정합니다.");
            lockedCards.Clear(); if (ids != null) foreach (var id in ids) lockedCards.Add(id);
        }
        // Unlocked cards not owned yet.
        IEnumerable<AugmentDefinition> Candidates => Catalog.augments.Where(a => !Has(a.id) && !lockedCards.Contains(a.id));

        // A full offer needs one stable card and two risk cards of different groups among the cards not owned yet.
        public bool CanDraw => CanDrawFrom(Candidates.ToList());
        static bool CanDrawFrom(List<AugmentDefinition> pool) =>
            pool.Any(a => a.Stable) && pool.Where(a => !a.Stable).Select(a => a.group).Distinct().Count() >= 2;

        // Equal chance per card: one stable, then a risk card, then a risk card of another group.
        AugmentDefinition[] Draw(List<AugmentDefinition> pool)
        {
            var stable = pool.Where(a => a.Stable).ToList();
            var risk = pool.Where(a => !a.Stable).ToList();
            var first = risk[random.Next(risk.Count)];
            var others = risk.Where(a => a.group != first.group).ToList();
            return new[] { stable[random.Next(stable.Count)], first, others[random.Next(others.Count)] };
        }

        // A free offer for the boss clear or the seal reward chest, kept by the caller until a card is granted. When the usual
        // one stable and two risk cards cannot be formed, up to three remaining cards are shown; empty when every card is owned.
        public AugmentDefinition[] DrawReward()
        {
            var pool = Candidates.ToList();
            if (CanDrawFrom(pool)) return Draw(pool);
            var rest = new List<AugmentDefinition>();
            while (rest.Count < Catalog.offeredCards && pool.Count > 0) { int i = random.Next(pool.Count); rest.Add(pool[i]); pool.RemoveAt(i); }
            return rest.ToArray();
        }

        // Owns one card: the card picked from a reward offer, or a development, sandbox and verification grant.
        public bool Grant(string id)
        {
            var chosen = Catalog.Find(id);
            if (chosen == null || Has(id)) return false;
            Add(chosen);
            return true;
        }

        void Add(AugmentDefinition chosen)
        {
            if (chosen.effect.growthKills > 0) { growthBasis[chosen.id] = MaxHealthRatio; GrowthKills = 0; }
            owned.Add(chosen);
            Revision++;
        }

        // Counts a defeat for 성장통; true when a maximum-health step was reached.
        public bool RecordKill()
        {
            if (growthBasis.Count == 0) return false;
            float before = MaxHealthRatio;
            GrowthKills++;
            return MaxHealthRatio != before;
        }

        // Maximum health over the augment-free base: the cards' ratios added, 성장통 added on its selection basis.
        public float MaxHealthRatio
        {
            get
            {
                float ratio = 1 + Sum(e => e.maxHealth);
                foreach (var a in owned)
                {
                    var e = a.effect;
                    if (!(e.growthKills > 0) || !growthBasis.TryGetValue(a.id, out float basis)) continue;
                    int steps = GrowthKills / (int)Math.Max(1, e.growthKills);
                    float growth = Math.Min(e.growthFinalRatio, e.growthStartRatio + steps * e.growthStepRatio);
                    ratio += (growth - 1) * basis;
                }
                return Math.Max(Catalog.minimumMaxHealthScale, ratio);
            }
        }

        public float HealingScale => Math.Max(0, 1 + Sum(e => e.healing));
        public float WalkSpeedBonus => Math.Max(Catalog.minimumWalkSpeedScale, 1 + Sum(e => e.walkSpeed)) - 1;
        public float BasicSpeedScale => Math.Max(Catalog.minimumBasicSpeedScale, 1 + Sum(e => e.basicSpeed));
        public float SkillCooldownReduction => Math.Min(Catalog.maximumSkillCooldownReduction, Math.Max(0, Sum(e => e.skillCooldown)));
        public float CritChance => Math.Min(Catalog.maximumCritChance, Math.Max(0, Sum(e => e.critChance)));
        public float DamageScale(float bonus) => Math.Max(Catalog.minimumDamageScale, 1 + bonus);
        public float IncomingScale(float bonus) => Math.Max(Catalog.minimumIncomingScale, 1 + bonus);
    }

    public sealed partial class WeaponGrowth
    {
        public MaintenanceAugments Augments { get; private set; }
        public void AttachAugments(MaintenanceAugments augments) { if (Augments == null && augments != null) Augments = augments; }
        public bool GrantAugment(string id)
        {
            if (Augments == null || !Augments.Grant(id)) return false;
            Publish();
            return true;
        }
    }
}
